/*
 * A142839  Primes congruent to 41 mod 61.
 * https://oeis.org/A142839
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, easy
 * Formula:   not stated
 * Range:     u8 n <= 2, u16 n <= 111, u32 n <= 1000, u64 n <= 1000,
 *            u128 n <= 1000, big any n
 * Helpers:   is_prime
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* Sequence: primes congruent to 41 (mod 61) – generated by testing
   each integer of the form 61·k+41 for primality. */

#include <stdlib.h>
#include <stddef.h>
#include "../utils/is_prime.h"

seq_t a(idx_t n)
{
    /* Return 0 for the fictitious index 0 – offset is 1. */
    if (n == 0) return 0;

    /* Cache of found primes in the residue class 41 mod 61. */
    static seq_t *cache   = NULL;
    static size_t cache_len = 0;
    static size_t cache_cap = 0;
    static idx_t  cur_k    = 0;           /* current k for candidate 61*k+41 */

    /* Extend cache until it contains at least n primes. */
    while (cache_len < n)
    {
        /* Compute candidate in idx_t to avoid overflow of seq_t
           during multiplication. */
        idx_t cand_i = (idx_t)61 * cur_k + (idx_t)41;

        /* Test primality: is_prime works for any idx_t value. */
        if (is_prime(cand_i))
        {
            /* Ensure cache capacity. */
            if (cache_len >= cache_cap)
            {
                size_t new_cap = cache_cap ? cache_cap * 2 : 16;
                seq_t *tmp = (seq_t *)realloc(cache, new_cap * sizeof(seq_t));
                if (!tmp) abort(); /* memory exhaustion */
                cache = tmp;
                cache_cap = new_cap;
            }
            /* Store the prime; cast to seq_t assuming it fits. */
            cache[cache_len++] = (seq_t)cand_i;
        }
        ++cur_k;   /* next candidate in the arithmetic progression */
    }

    return cache[n - 1];
}
